library(euaiact)
f <- "EUAIACT_2026_07_27"
t <- function(id,data) pruefe_tatbestand(id,data,f)
four <- berechne_regel("AIA_112_002_TERMIN",list(evaluationszyklus_index=1),f)
three <- berechne_regel("AIA_112_007_TERMIN",list(evaluationszyklus_index=1),f)
stopifnot(four$wert=="2032-08-02",three$wert=="2031-08-02")
duty <- ermittle_pflicht("P_AIA_112_002",list(schluss_kommission=TRUE),f)
stopifnot(identical(duty$wert$fristregel_ids,list("AIA_112_002_TERMIN")),duty$wert$erfuellung=="NICHT_GEPRUEFT")
data <- setNames(rep(list(TRUE),length(eingabevertrag("AIA_112_002_KRITERIEN")$felder)),names(eingabevertrag("AIA_112_002_KRITERIEN")$felder))
data$evaluation_112_bericht_oder_feststellungen_dem_parlament_und_rat_uebermittelt <- FALSE
stopifnot(identical(t("AIA_112_002_KRITERIEN",data)$wert,FALSE))
duty <- ermittle_pflicht("P_AIA_004_001",list(ki_system=TRUE,anbieterrolle=FALSE,betreiberrolle=TRUE),f)
stopifnot(isTRUE(duty$wert$ausloeser_erfuellt),duty$wert$erfuellung=="NICHT_GEPRUEFT")
data <- list(ki_kompetenz_massnahmen_fuer_personal_und_im_auftrag_handlende_personen=TRUE,ki_kompetenz_technisches_wissen_erfahrung_bildung_ausbildung_beruecksichtigt=TRUE,ki_kompetenz_konkreter_einsatzkontext_beruecksichtigt=TRUE,ki_kompetenz_betroffene_personen_oder_gruppen_beruecksichtigt=TRUE)
stopifnot(isTRUE(t("AIA_004_001_KRITERIEN",data)$wert));data["ki_kompetenz_konkreter_einsatzkontext_beruecksichtigt"] <- list(NULL)
stopifnot(t("AIA_004_001_KRITERIEN",data)$status=="EINGABE_FEHLT")
duty <- ermittle_pflicht("P_AIA_041_004_AUFHEBUNG",list(harmonisierte_normreferenz_fuer_ersetzende_anforderungen_im_amtsblatt_veroeffentlicht=TRUE,gemeinsame_spezifikation_deckt_dieselben_anforderungen_oder_pflichten_wie_norm=TRUE),f)
stopifnot(isTRUE(duty$wert$ausloeser_erfuellt),identical(t("AIA_041_004_AUFHEBUNGSNACHWEIS",list(kommission_hat_durch_norm_abgedeckte_spezifikationsakte_oder_teile_aufgehoben=FALSE))$wert,FALSE))
duty <- ermittle_pflicht("P_AIA_078_002_SICHERHEIT",list(an_ai_act_anwendung_beteiligte_behoerde=TRUE,information_bei_ai_act_aufgaben_erlangt=TRUE),f)
stopifnot(isTRUE(duty$wert$ausloeser_erfuellt),identical(t("AIA_078_002_SICHERHEITSNACHWEIS",list(behoerde_hat_angemessene_wirksame_cybersicherheit_fuer_erlangte_information_eingerichtet=FALSE))$wert,FALSE))
request <- ermittle_pflicht("P_AIA_078_002_ANFORDERUNG",list(an_ai_act_anwendung_beteiligte_behoerde=TRUE,behoerde_fordert_daten_fuer_ai_act_befugnisse_an=TRUE),f)
stopifnot(isTRUE(request$wert$ausloeser_erfuellt),identical(t("AIA_078_002_ERFORDERLICHKEIT",list(behoerdlich_angeforderte_daten_strikt_fuer_risiko_und_befugnisse_erforderlich=FALSE))$wert,FALSE))
cat("Four source-closure workflows passed\n")

end <- pruefe_bestandsfrist("GROSS_IT_ANHANG_X", "2031-01-02", ereignisse=list(inverkehrbringen=list(erfolgt=TRUE, datum="2026-01-01")), quellenfassung=f)
stopifnot(end$wert$friststatus == "NACH_FRISTTAG")
duty <- ermittle_pflicht("P_AIA_111_001_EVALUATION", list(evaluation_betrifft_gross_it_system_nach_anhang_x=TRUE, evaluation_nach_einrichtungsrechtsakt_oder_bei_dessen_ersetzung_aenderung=TRUE), f)
stopifnot(isTRUE(duty$wert$ausloeser_erfuellt), duty$wert$erfuellung=="NICHT_GEPRUEFT", identical(t("AIA_111_001_EVALUATIONSNACHWEIS",list(ai_act_anforderungen_in_gross_it_evaluation_beruecksichtigt=FALSE))$wert,FALSE))
cat("Additional independent large-IT evaluation workflow passed\n")
